query InsightsPageQuery(
  $filter: SpotifyStatsFilter!
  $allPlays: SpotifyStatsFilter!
  $bucket: SpotifyTimeBucket!
) {
  spotifyEnrichment {
    listeningCoverage
  }
  spotifyStats(filter: $filter) {
    topGenres(first: 10) {
      edges {
        rank
        plays
        minutesPlayed
        node {
          name
        }
      }
    }
    genreTimeline(bucket: $bucket) {
      genre
      points {
        start
        minutesPlayed
      }
    }
    musicAge {
      averageYears
      newShare
      oldestYear
      oldest {
        name
        artistName
        id
      }
    }
    decades: breakdown(by: DECADE) {
      key
      label
      plays
      minutesPlayed
    }
    listeningDays {
      activeDays
      spanDays
      longestStreak {
        start
        end
        days
      }
      latestStreak {
        start
        end
        days
      }
    }
    sessions {
      count
      averageMinutes
      longest {
        start
        plays
        minutesPlayed
      }
    }
    topDays(first: 8) {
      date
      plays
      minutesPlayed
      topArtist {
        name
        id
      }
    }
    onRepeat(first: 8) {
      date
      plays
      item {
        id
        uri
        name
        artistName
        artworkUrl
      }
    }
    discoveries(first: 10) {
      edges {
        node {
          artist {
            id
            name
            imageUrl
          }
          firstPlayed
          minutesPlayed
          firstItem {
            name
            id
          }
        }
      }
    }
    forgottenArtists(first: 10) {
      edges {
        node {
          artist {
            id
            name
            imageUrl
          }
          minutesPlayed
          lastPlayed
        }
      }
    }
    device: breakdown(by: DEVICE) {
      label
      plays
      minutesPlayed
    }
    country: breakdown(by: COUNTRY) {
      label
      plays
      minutesPlayed
    }
    shuffle: breakdown(by: SHUFFLE) {
      label
      plays
      minutesPlayed
    }
    offline: breakdown(by: OFFLINE) {
      label
      plays
      minutesPlayed
    }
    endReason: breakdown(by: END_REASON) {
      label
      plays
      minutesPlayed
    }
  }
  skips: spotifyStats(filter: $allPlays) {
    completion {
      average
      finishedShare
    }
    mostAbandoned(first: 8) {
      plays
      averageCompletion
      item {
        id
        uri
        name
        artistName
        artworkUrl
      }
    }
    mostSkippedArtists: artistSkipRates(order: MOST_SKIPPED, first: 10) {
      rank
      plays
      skips
      skipRate
      artist {
        id
        name
        imageUrl
      }
    }
    leastSkippedArtists: artistSkipRates(order: LEAST_SKIPPED, first: 10) {
      rank
      plays
      skips
      skipRate
      artist {
        id
        name
        imageUrl
      }
    }
    mostSkipped(first: 8) {
      plays
      skips
      skipRate
      item {
        id
        uri
        name
        artistName
        artworkUrl
      }
    }
  }
}

